interface ManualInvoiceModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (data: any, options?: { lojaIdOverride?: number | null; formaPagamento?: string; creditCardId?: number | null }) => Promise<void>;
  initialData?: any;
  isSaving: boolean;
  stores?: { id: number; name: string }[];
  selectedStoreId?: number | null;
  creditCards?: { id: number; nome: string; bandeira: string; ultimos_digitos?: string; loja_id?: number }[];
}

export function ManualInvoiceModal({
  isOpen,
  onClose,
  onSave,
  initialData,
