          if (pages.length > 0) {
            const fname = `${baseName}_f${i + 1}_p1.jpg`;
            const pageFile = toFile(pages[0], fname);
            const { error: upErr } = await supabase.storage.from('notas-fiscais').upload(fname, pageFile);
            if (!upErr) {
              const { data: pub } = supabase.storage.from('notas-fiscais').getPublicUrl(fname);
              uploadedUrls.push(pub?.publicUrl || null);
            } else {
              uploadedUrls.push(null);
            }
          }
        } else {
          const fileExt = file.name.split('.').pop()?.toLowerCase() || 'jpg';
          const fileName = `${baseName}_f${i + 1}.${fileExt}`;
          const { error: uploadError } = await supabase.storage
            .from('notas-fiscais')
            .upload(fileName, file);
          if (!uploadError) {
            const { data: publicData } = supabase.storage
              .from('notas-fiscais')
              .getPublicUrl(fileName);
            uploadedUrls.push(publicData?.publicUrl || null);
          } else {
            uploadedUrls.push(null);
          }
        }
      }

      fotoUrl = uploadedUrls[0] ?? fotoUrl;
      fotoUrl2 = uploadedUrls[1] ?? fotoUrl2;
    }

