} else {
  // Insert — R4: nunca gravar loja_id nulo silenciosamente em nota nova
  const lojaId = options?.lojaIdOverride ?? (canSelectStoreNF() ? (comprasLojaId !== 'all' ? comprasLojaId : undefined) : selectedStore?.id);
  if (!lojaId) {
    toast.error('Selecione uma loja específica para lançar a nota.');
    setIsSaving(false);
    return;
  }
  const { data: nota, error: notaError } = await supabase
    .from('notas_fiscais')
    .insert({
      numero_nota: dataToSave.numero_nota,
      fornecedor: dataToSave.fornecedor,
      cnpj_emitente: dataToSave.cnpj_emitente || null,
      endereco_emitente: dataToSave.endereco_emitente || null,
      data_nota: dataToSave.data_nota,
      data_vencimento: dataToSave.data_vencimento || null,
      data_recebimento: dataToSave.data_recebimento || null,
      valor_total: dataToSave.valor_total,
      status: 'processada',
      user_id: userId,
      imagem_url: fotoUrl,
      imagem_url_2: fotoUrl2,
      loja_id: lojaId,
      forma_pagamento: options?.formaPagamento || null,
      credit_card_id: options?.formaPagamento === 'cartao_credito' && options?.creditCardId ? options.creditCardId : null,
    })
    .select()
    .single();

  if (notaError) throw notaError;
  notaId = nota.id;

  // Auto-sync: Route to credit card or contas a pagar
  try {
    if (dataToSave.valor_total) {
      const isCartao = options?.formaPagamento === 'cartao_credito' && options?.creditCardId;

      if (isCartao) {
        // Route to credit card transactions instead of contas_pagar_receber
        const cardId = options.creditCardId!;
        // Get or create the invoice for the month
        const purchaseDate = new Date(dataToSave.data_nota || new Date());
        // Fetch card to check dia_fechamento
        const { data: cardData } = await supabase.from('credit_cards').select('dia_fechamento, dia_vencimento').eq('id', cardId).maybeSingle();
        const fechamento = cardData?.dia_fechamento || 25;
        const invoiceMonth = new Date(purchaseDate);
        if (purchaseDate.getDate() > fechamento) invoiceMonth.setMonth(invoiceMonth.getMonth() + 1);
        invoiceMonth.setDate(1);
        const mesRef = `${invoiceMonth.getFullYear()}-${String(invoiceMonth.getMonth() + 1).padStart(2, '0')}-01`;

        // Upsert invoice
        let invoiceId: number | null = null;
        const { data: existingInv } = await supabase
          .from('credit_card_invoices')
          .select('id')
          .eq('credit_card_id', cardId)
          .eq('mes_referencia', mesRef)
          .maybeSingle();

        if (existingInv) {
          invoiceId = existingInv.id;
        } else {
          const vencDate = new Date(invoiceMonth);
          vencDate.setMonth(vencDate.getMonth() + 1);
          vencDate.setDate(cardData?.dia_vencimento || 10);
          const vencStr = `${vencDate.getFullYear()}-${String(vencDate.getMonth() + 1).padStart(2, '0')}-${String(vencDate.getDate()).padStart(2, '0')}`;
          const { data: newInv } = await supabase
            .from('credit_card_invoices')
            .insert({ credit_card_id: cardId, mes_referencia: mesRef, status: 'aberta', data_vencimento: vencStr })
            .select('id')
            .single();
          invoiceId = newInv?.id || null;
        }

        await supabase.from('credit_card_transactions').insert({
          credit_card_id: cardId,
          invoice_id: invoiceId,
          loja_id: lojaId ?? null,
          nota_fiscal_id: notaId,
          data: dataToSave.data_nota || new Date().toISOString().split('T')[0],
          descricao: `NF ${dataToSave.numero_nota || 'S/N'} - ${dataToSave.fornecedor}`,
          valor: dataToSave.valor_total,
          categoria: 'Fornecedores',
          parcela_atual: 1,
          total_parcelas: 1,
          origem: 'api',
        });
      } else {
        // Normal flow: create conta a pagar
        const txPayload = {
          descricao: `NF ${dataToSave.numero_nota || 'S/N'} - ${dataToSave.fornecedor}`,
          valor: dataToSave.valor_total,
          data_vencimento: dataToSave.data_vencimento || null,
          data_competencia: dataToSave.data_nota || null,
          tipo: 'despesa',
          status: 'pendente',
          origem: 'nota_fiscal',
          categoria: 'fornecedores',
          forma_pagamento: options?.formaPagamento || null,
          loja_id: lojaId || null,
          numero_parcelas: 1,
          nota_fiscal_id: notaId,
          url_comprovante: fotoUrl,
        };
        await supabase.from('contas_pagar_receber').insert(txPayload);
      }
    }
  } catch (syncErr) {

